// CreateTableWithDBType creates the Vendor Ledger Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *VendorLedgerEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, VendorLedgerEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetVendorLedgerEntryPostgresTableSchema()
	} else {
		schema = GetVendorLedgerEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Vendor Ledger Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *VendorLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, VendorLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (vendor_no, open)`,
		fmt.Sprintf("%s$Vendor Ledger Entry$vendor_open", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor_open: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (vendor_no)`,
		fmt.Sprintf("%s$Vendor Ledger Entry$vendor", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, document_no)`,
		fmt.Sprintf("%s$Vendor Ledger Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (posting_date)`,
		fmt.Sprintf("%s$Vendor Ledger Entry$posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index posting_date: %w", err)
	}
	var keys []sift.Key
	for _, spec := range vendorLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, VendorLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, VendorLedgerEntryTableName, keys)
}

// vendorLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func vendorLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "vendor_open",
			Fields: []sift.Column{{Name: "vendor_no", Kind: sift.KindText}, {Name: "open", Kind: sift.KindBool}},
			Sums:   []sift.Column{{Name: "remaining_amt_lcy", Kind: sift.KindDecimal}, {Name: "purchase_lcy", Kind: sift.KindDecimal}, {Name: "amount_lcy", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *VendorLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, VendorLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range vendorLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, VendorLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: VendorLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, VendorLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

